glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif

void main () {
  vec4 pos = vec4(a_position, 1);

  pos = cc_matViewProj * pos;

  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif

  v_color = a_color;

  gl_Position = pos;
}

glsl3.frag:
precision highp float;

in vec4 v_color;

#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
uniform sampler2D normalMap;
#endif

uniform PROPERTIES {
  vec4 lightPos;
}

void main () {

  vec4 LightColor = vec4(254.0/255.0, 173.0/255.0, 95.0/255.0, .3);
  vec4 AmbientColor = vec4(1.0, 1.0, 1.0, .9);
  vec3 Falloff = vec3(0.01, .01, 0.1);
  vec4 DiffuseColor = texture2D(texture, v_uv0);
  vec3 NormalMap = texture2D(normalMap, v_uv0).rgb;
  vec3 LightPos = lightPos.xyz;
  vec3 LightDir = LightPos;

  float D = length(LightDir);
  vec3 N = normalize(NormalMap * 2.0 - 1.0);
  vec3 L = normalize(LightDir);
  vec3 Diffuse = (LightColor.rgb * LightColor.a) * max(dot(N, L), 0.0);
  vec3 Ambient = AmbientColor.rgb * AmbientColor.a;
  float Attenuation = 1.0 / ( Falloff.x + (Falloff.y*D) + (Falloff.z*D*D) );
  vec3 Intensity = Ambient + Diffuse * Attenuation;
  vec3 FinalColor = DiffuseColor.rgb * Intensity;
  vec4 o = v_color * vec4(FinalColor, DiffuseColor.a);
  #if CC_USE_ALPHA_ATLAS_TEXTURE
    o.a *= texture2D(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  gl_FragColor = o;
}

